    '.foo',
    '#main',
    'div.foo.bar#main',
    'ul>li.item$*3',
    'div>span+strong',
    'div>p^aside',
    'div>p^^aside',
    '(header+main)>p',
    'div>(header+main)>p',
    '(header+main)*2',
